 const map=spec.widths.map((width,layer)=>{const row=[],shift=Math.floor(random()*develop[devIndex%develop.length].length);for(let lane=0;lane<width;lane++){const event=G.EVENTS[Math.floor(random()*G.EVENTS.length)],options=develop[devIndex%develop.length],type=layer===14?'boss':fight.has(layer)?(layer>2&&random()<.24?'elite':'battle'):options[(lane+shift)%options.length];row.push({id:'a'+a+'_'+(layer===14?'boss':'n'+layer+'_'+lane),type,layer,lane,act:a,x:width===1?.5:.1+lane*.8/(width-1),name:type==='event'?event.name:names[type],eventId:event.id,links:[]});}if(!fight.has(layer))devIndex++;return row;});
